import json
import os
from pathlib import Path
import subprocess
import time
from urllib.request import urlopen

work = Path(__file__).parent
# Reuse the just-built images while giving this test its own network and volumes.
extra = work / "override.yml"
extra.write_text(extra.read_text().replace(
    "  backend:\n", "  backend:\n    image: frame-inventory-exercise-main-backend\n",
).replace(
    "  frontend:\n", "  frontend:\n    image: frame-inventory-exercise-main-frontend\n",
).replace(
    "  postgres:\n", "  bff:\n    image: frame-inventory-exercise-main-bff\n  postgres:\n",
))
project = work.name.lower().replace('.', '-')
env = {**os.environ, "INVENTORY_IMPORT_LOCAL_TOKEN": (work / "operator-token").read_text().strip()}
compose = ["docker", "compose", "-p", project, "-f", "docker-compose.yml", "-f", "docker-compose.local-import.yml", "-f", str(extra), "--profile", "import"]
try:
    subprocess.run(compose + ["up", "--no-build", "-d", "--wait", "--wait-timeout", "60", "frontend"], env=env, check=True)
    subprocess.run(compose + [
        "exec", "-T", "aws", "awslocal", "s3api", "put-bucket-cors", "--bucket", "frame-inventory-import-local",
        "--cors-configuration", json.dumps({"CORSRules": [{
            "AllowedOrigins": ["http://127.0.0.1:13036"], "AllowedMethods": ["PUT"],
            "AllowedHeaders": ["Content-Type", "If-None-Match"], "ExposeHeaders": ["ETag", "x-amz-version-id"],
        }]}),
    ], env=env, check=True)
    for attempt in range(30):
        try:
            with urlopen("http://127.0.0.1:13036", timeout=5) as response:
                if response.status == 200:
                    break
        except OSError:
            if attempt == 29:
                raise
        time.sleep(1)
    node = Path.home() / ".nvm/versions/node/v22.17.1/bin/node"
    subprocess.run([str(node), str(work / "verify.cjs")], check=True)
finally:
    subprocess.run(compose + ["down", "--volumes"], env=env, check=True)

