  {id:"GLO-36",patch:[{op:"replace",old_string:`${link} starts Temporal, the S3/SQS emulator, and the Python DELTA worker from the main Compose stack.`,new_string:`${link} merged into \`main\`. The main Compose stack now starts Temporal, the S3/SQS emulator, and the Python DELTA worker.`}]}
];
await Promise.allSettled(changes.map(async change=>{const r=await tools.mcp__linear__save_issue(change);const d=r.structuredContent??JSON.parse(r.content[0].text);text({id:d.id,status:d.status,url:d.url,confirmed:d.description?.includes("merged into `main`"),error:r.isError??false});}));

const auth=load("followup1");
const release=load("followup2");
const tail=auth.description.split("\n\n").at(-1);
const change={
  id:"GLO-28",
  parentId:null,
  removeBlocks:["GLO-36","GLO-31"],
  relatedTo:["GLO-26","GLO-11"],
  patch:[{op:"replace",old_string:tail,new_string:`This standalone follow-up owns deployed authorization and DELTA release verification. The local DELTA flow was verified using the loopback-only test operator. [GLO-36](${release.url})

## Deployed release checks

- Implement the deployed operator identity contract, DELTA and force-overwrite permissions, and owner-only access to job status and row errors.
- After authorization is in place, run the supplied 1,000-row CSV through the deployed browser app. Verify re-upload counts, row diagnostics, frame history, and access controls.
- Verify the deployed Grafana dashboard for stuck jobs, dispatch failures, and apply duration.`}]
};
const r=await tools.mcp__linear__save_issue(change);const d=r.structuredContent??JSON.parse(r.content[0].text);store("movedAuth",d);text({error:r.isError??false,id:d.id,title:d.title,parentId:d.parentId,status:d.status,description:d.description,relations:d.relations});

const d=load("movedGLO-36");const auth=load("followup1");const changes=[
  ["check",tools.mcp__linear__get_issue({id:"GLO-28",fields:["title","status","url","parentId","relations"],includeRelations:true})],
  ["delta",tools.mcp__linear__save_issue({
    id:"GLO-36",
    state:"Done",
    title:"Verify the local DELTA import flow",
    patch:[
      {op:"replace",old_string:d.description.split("\n\n")[0],new_string:"Verify the DELTA import in the local Compose stack using the loopback-only operator. Upload the supplied 1,000-row CSV and check re-upload counts, frame history, authorization errors, retries, input limits, retention, and dashboard metrics. Record the AWS infrastructure smoke test."},
      {op:"replace",old_string:d.description.split("\n\n").at(-1),new_string:`Local DELTA verification is complete. Deployed authorization, the deployed browser smoke test, and deployed dashboard verification are tracked in [GLO-28](${auth.url}).`},
    ],
  })]];
const results=await Promise.allSettled(changes.map(async ([k,p])=>{const r=await p;const d=r.structuredContent??JSON.parse(r.content[0].text);store(`followupResult${k}`,d);text({k,id:d.id,title:d.title,status:d.status,parentId:d.parentId,url:d.url,relations:d.relations,error:r.isError??false});}));for(const r of results){if(r.status==="rejected")text(String(r.reason));}

const epic=load("followup0");const auth=load("followupResultcheck");const delta=load("followupResultdelta");const oldDelta=load("followup2");
const p=[
  tools.mcp__linear__save_issue({id:"GLO-26",patch:[
    {op:"replace",old_string:"An authorized operator imports the supplied 1,000-row CSV through the app, sees results and history, and can retry without duplicate versions. Snapshot rollout has its own safety and verification gate.",new_string:"An operator using the local test credential imports the supplied 1,000-row CSV through the app, sees results and history, and can retry without duplicate versions. FULL_SNAPSHOT rollout has its own safety and verification gate."},
    {op:"replace",old_string:epic.description.split("\n\n").at(-1),new_string:`Local DELTA verification is complete in [GLO-36](${delta.url}). Deployed authorization and the deployed DELTA browser and dashboard checks are tracked independently in [GLO-28](${auth.url}). The remaining epic work is the FULL_SNAPSHOT safety contract and scoped retirement rollout.`},
  ]}),
  tools.mcp__linear__save_issue({id:"GLO-28",patch:[{op:"replace",old_string:`[GLO-36](<${oldDelta.url}>)`,new_string:`[GLO-36](${delta.url})`}]}),
];
const results=await Promise.allSettled(p.map(async q=>{const r=await q;const d=r.structuredContent??JSON.parse(r.content[0].text);text({id:d.id,status:d.status,url:d.url,error:r.isError??false,tail:d.description?.split("\n\n").at(-1)});}));for(const r of results){if(r.status==="rejected")text(String(r.reason));}

